// Requires react-native-gesture-handler, react-native-reanimated and its Babel plugin
import { Gesture, GestureDetector, GestureHandlerRootView } from 'react-native-gesture-handler';
import Animated, { useAnimatedStyle, useSharedValue, withSpring } from 'react-native-reanimated';

function DraggableBox() {
  const offsetX = useSharedValue(0);
  const startX = useSharedValue(0);

  const pan = Gesture.Pan()
    .onBegin(() => {
      startX.value = offsetX.value;
    })
    .onUpdate((event) => {
      offsetX.value = startX.value + event.translationX;
    })
    .onEnd(() => {
      offsetX.value = withSpring(0);   // spring back to the origin
    });

  const animatedStyle = useAnimatedStyle(() => ({
    transform: [{ translateX: offsetX.value }],
  }));

  return (
    <GestureDetector gesture={pan}>
      <Animated.View
        style={[{ width: 80, height: 80, backgroundColor: '#61DAFB' }, animatedStyle]}
      />
    </GestureDetector>
  );
}

export default function App() {
  return (
    <GestureHandlerRootView style={{ flex: 1 }}>
      <DraggableBox />
    </GestureHandlerRootView>
  );
}

import AsyncStorage from '@react-native-async-storage/async-storage';

// AsyncStorage stores strings only
async function saveTheme(theme) {
  await AsyncStorage.setItem('theme', theme);
}

async function loadTheme() {
  return AsyncStorage.getItem('theme');   // resolves to string or null
}

async function clearTheme() {
  await AsyncStorage.removeItem('theme');
}

// Objects must be serialized by hand
async function saveUser(user) {
  await AsyncStorage.setItem('user', JSON.stringify(user));
}

async function loadUser() {
  const raw = await AsyncStorage.getItem('user');
  return raw ? JSON.parse(raw) : null;
}

